/**
 * Innovive HubSpot UTM attribution bridge.
 *
 * Keeps first-party UTM values from the landing URL and writes them to the
 * HubSpot contact after a successful form submit. HubSpot tracking still
 * loads only after CookieYes analytics consent.
 *
 * Volado Labs, 2026-09-01
 */
add_action( 'rest_api_init', function () {
	register_rest_route(
		'volado/v1',
		'/hs-pat',
		array(
			'methods'             => 'POST',
			'permission_callback' => function () {
				return current_user_can( 'manage_options' );
			},
			'callback'            => function ( $req ) {
				$token = sanitize_text_field( $req->get_param( 'token' ) );
				if ( ! $token ) {
					return new WP_Error( 'no_token', 'Missing token', array( 'status' => 400 ) );
				}
				update_option( 'volado_innovive_hs_pat', $token, false );
				return array( 'ok' => true, 'len' => strlen( $token ) );
			},
		)
	);
	register_rest_route(
		'volado/v1',
		'/hs-utm',
		array(
			'methods'             => 'POST',
			'permission_callback' => function () {
				return true;
			},
			'callback'            => 'volado_innovive_hs_utm',
		)
	);
} );

function volado_innovive_hs_utm( $req ) {
	$body  = $req->get_json_params();
	if ( ! is_array( $body ) ) {
		$body = array();
	}
	$nonce = isset( $body['nonce'] ) ? $body['nonce'] : $req->get_param( 'nonce' );
	if ( ! wp_verify_nonce( sanitize_text_field( $nonce ), 'volado_hs_utm' ) ) {
		return new WP_Error( 'bad_nonce', 'Invalid nonce', array( 'status' => 403 ) );
	}
	$email_raw = isset( $body['email'] ) ? $body['email'] : $req->get_param( 'email' );
	$email     = sanitize_email( $email_raw );
	if ( ! is_email( $email ) ) {
		return new WP_Error( 'bad_email', 'Invalid email', array( 'status' => 400 ) );
	}
	$utm = isset( $body['utm'] ) ? $body['utm'] : $req->get_param( 'utm' );
	if ( ! is_array( $utm ) ) {
		$utm = array();
	}
	$allowed = array( 'utm_source', 'utm_medium', 'utm_campaign', 'utm_content', 'utm_term' );
	$props   = array();
	foreach ( $allowed as $field ) {
		if ( empty( $utm[ $field ] ) ) {
			continue;
		}
		$props[ $field ] = substr( sanitize_text_field( $utm[ $field ] ), 0, 255 );
	}
	if ( ! $props ) {
		return array( 'ok' => true, 'updated' => false, 'reason' => 'no_utm' );
	}
	$token = get_option( 'volado_innovive_hs_pat' );
	if ( ! $token ) {
		return new WP_Error( 'no_pat', 'HubSpot token missing', array( 'status' => 500 ) );
	}
	$search = wp_remote_post(
		'https://api.hubapi.com/crm/v3/objects/contacts/search',
		array(
			'timeout' => 20,
			'headers' => array(
				'Authorization' => 'Bearer ' . $token,
				'Content-Type'  => 'application/json',
			),
			'body'    => wp_json_encode(
				array(
					'filterGroups' => array(
						array(
							'filters' => array(
								array(
									'propertyName' => 'email',
									'operator'     => 'EQ',
									'value'        => $email,
								),
							),
						),
					),
					'properties'   => array( 'email', 'createdate' ),
					'limit'        => 1,
				)
			),
		)
	);
	if ( is_wp_error( $search ) ) {
		return new WP_Error( 'hs_search', $search->get_error_message(), array( 'status' => 502 ) );
	}
	$code = wp_remote_retrieve_response_code( $search );
	$data = json_decode( wp_remote_retrieve_body( $search ), true );
	if ( 200 !== intval( $code ) ) {
		return new WP_Error( 'hs_search_http', 'HubSpot search failed', array( 'status' => 502 ) );
	}
	$results = isset( $data['results'] ) ? $data['results'] : array();
	if ( ! $results ) {
		return array( 'ok' => true, 'updated' => false, 'reason' => 'no_contact' );
	}
	$cid   = $results[0]['id'];
	$patch = wp_remote_request(
		'https://api.hubapi.com/crm/v3/objects/contacts/' . rawurlencode( $cid ),
		array(
			'method'  => 'PATCH',
			'timeout' => 20,
			'headers' => array(
				'Authorization' => 'Bearer ' . $token,
				'Content-Type'  => 'application/json',
			),
			'body'    => wp_json_encode( array( 'properties' => $props ) ),
		)
	);
	if ( is_wp_error( $patch ) ) {
		return new WP_Error( 'hs_patch', $patch->get_error_message(), array( 'status' => 502 ) );
	}
	$pcode = wp_remote_retrieve_response_code( $patch );
	if ( $pcode < 200 || $pcode >= 300 ) {
		return new WP_Error( 'hs_patch_http', 'HubSpot patch failed', array( 'status' => 502 ) );
	}
	return array( 'ok' => true, 'updated' => true, 'id' => $cid );
}

