<!-- Innovive HubSpot UTM attribution bridge (Volado Labs, 2026-09-01) -->
<script>
(function () {
  'use strict';

  var PORTAL_ID = '246069906';
  var STORAGE_KEY = 'innovive_hs_utm_v1';
  var UTM_FIELDS = ['utm_source', 'utm_medium', 'utm_campaign', 'utm_content', 'utm_term'];
  var NONCE = <?php echo wp_json_encode( $nonce ); ?>;
  var currentUtm = readCurrentUrl();

  function hasConsent(category) {
    try {
      var match = document.cookie.match(/(?:^|;\s*)cookieyes-consent=([^;]+)/);
      if (!match) return false;
      var consent = decodeURIComponent(match[1]);
      return new RegExp('(?:^|,)' + category + ':yes(?:,|$)').test(consent);
    } catch (error) {
      return false;
    }
  }

  function clean(value) {
    return String(value || '').trim().slice(0, 255);
  }

  function readCurrentUrl() {
    var values = {};
    try {
      var params = new URLSearchParams(window.location.search);
      UTM_FIELDS.forEach(function (field) {
        var value = clean(params.get(field));
        if (value) values[field] = value;
      });
    } catch (error) {}
    return values;
  }

  function hasUtm(values) {
    return UTM_FIELDS.some(function (field) { return Boolean(values && values[field]); });
  }

  function saveCurrentUtm() {
    if (!hasUtm(currentUtm)) return;
    try {
      sessionStorage.setItem(STORAGE_KEY, JSON.stringify(currentUtm));
    } catch (error) {}
  }

  function getSessionUtm() {
    if (hasUtm(currentUtm)) return currentUtm;
    try {
      var saved = JSON.parse(sessionStorage.getItem(STORAGE_KEY) || '{}');
      return hasUtm(saved) ? saved : {};
    } catch (error) {
      return {};
    }
  }

  function loadHubSpot() {
    if (!hasConsent('analytics')) return;
    window._hsq = window._hsq || [];
    if (document.getElementById('hs-script-loader')) return;
    var script = document.createElement('script');
    script.id = 'hs-script-loader';
    script.async = true;
    script.defer = true;
    script.src = 'https://js.hs-scripts.com/' + PORTAL_ID + '.js';
    document.head.appendChild(script);
  }

  function getEventForm(event) {
    try {
      if (window.HubSpotFormsV4 && typeof window.HubSpotFormsV4.getFormFromEvent === 'function') {
        return window.HubSpotFormsV4.getFormFromEvent(event);
      }
    } catch (error) {}
    return null;
  }

  function readEmail(form) {
    try {
      if (form && typeof form.getFormFieldValues === 'function') {
        var fields = form.getFormFieldValues() || [];
        for (var i = 0; i < fields.length; i += 1) {
          if (fields[i] && fields[i].name === 'email') return clean(fields[i].value);
        }
      }
    } catch (error) {}
    var emailNode = document.querySelector('input[name="email"], input[type="email"]');
    return emailNode ? clean(emailNode.value) : '';
  }

  function sendUtm(email, values) {
    if (!email || !hasUtm(values)) return;
    try {
      fetch('/wp-json/volado/v1/hs-utm', {
        method: 'POST',
        credentials: 'same-origin',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ email: email, utm: values, nonce: NONCE })
      });
    } catch (error) {}
  }

  function onSuccess(event) {
    var values = getSessionUtm();
    var form = getEventForm(event);
    var email = readEmail(form);
    sendUtm(email, values);
    if (!hasConsent('analytics') || !hasUtm(values) || !email) return;
    window._hsq = window._hsq || [];
    var identity = { email: email };
    UTM_FIELDS.forEach(function (field) {
      if (values[field]) identity[field] = values[field];
    });
    window._hsq.push(['identify', identity]);
    window._hsq.push(['trackPageView']);
  }

  saveCurrentUtm();
  loadHubSpot();
  document.addEventListener('cookieyes_consent_update', function () {
    saveCurrentUtm();
    loadHubSpot();
  });
  window.addEventListener('hs-form-event:on-submission:success', onSuccess);
})();
</script>
